// A .d.ts-less CJS package whose whole body is UNTYPED bitwise arithmetic:
// the varint / zigzag / 64-bit-split core every generated protobuf runtime
// is written in (protobufjs's Writer.uint32, LongBits.zzEncode and
// LongBits.length, reduced to plain functions).
//
// Nothing here is annotated, so every parameter is implicit `any` and every
// operand of every `&`, `|`, `^`, `<<`, `>>`, `>>>` reaches lowering as a
// checked-dynamic value. That is the ONLY thing this package tests: the
// operators are ToInt32/ToUint32 by specification — no ToPrimitive branch,
// no string arm, the result always a number — so a static build owes Node
// the same bytes, and this fixture is the differential that says so.
'use strict';

function writeVarint32(out, value) {
  while (value > 127) {
    out.push((value & 127) | 128);
    value = value >>> 7;
  }
  out.push(value & 127);
}

function zigZag32(value) {
  return ((value << 1) ^ (value >> 31)) >>> 0;
}

function loZigZag(lo, hi) {
  var mask = hi >> 31;
  return ((lo << 1) ^ mask) >>> 0;
}

function hiZigZag(lo, hi) {
  var mask = hi >> 31;
  return (((hi << 1) | (lo >>> 31)) ^ mask) >>> 0;
}

// protobufjs's LongBits.length, byte for byte: the 64-bit varint size
// ladder, and the densest run of `>>>` / `<<` / `|` in the runtime.
function varint64Len(lo, hi) {
  var part0 = lo >>> 0;
  var part1 = ((lo >>> 28) | (hi << 4)) >>> 0;
  var part2 = hi >>> 24;
  if (part2 !== 0) return part2 < 128 ? 9 : 10;
  if (part1 !== 0) return part1 < 16384 ? (part1 < 128 ? 5 : 6) : part1 < 2097152 ? 7 : 8;
  return part0 < 16384 ? (part0 < 128 ? 1 : 2) : part0 < 2097152 ? 3 : 4;
}

// The wire tag: (fieldNumber << 3) | wireType, on untyped arguments.
function tag(field, wire) {
  return (field << 3) | wire;
}

// Compound bitwise assignment on an untyped local, and the shift-count
// masking JS specifies (counts are taken mod 32).
function rotl(value, bits) {
  var v = value >>> 0;
  v = ((v << bits) | (v >>> (32 - bits))) >>> 0;
  return v;
}

module.exports = {
  writeVarint32: writeVarint32,
  zigZag32: zigZag32,
  loZigZag: loZigZag,
  hiZigZag: hiZigZag,
  varint64Len: varint64Len,
  tag: tag,
  rotl: rotl,
  // Unary complement on an untyped parameter, and the `^`/`|` pair.
  mix: function mix(a, b) {
    return ((a ^ b) | 0) >>> 0;
  },
  mask8: function mask8(x) {
    return x & 255;
  },
};
